INSERT INTO "changelog_entry" ("entry_date", "summary") VALUES
('2026-11-22', 'Jeux : « 🐺 Loups-garous », l''aide du meneur. Le deck est proposé selon le nombre de joueurs (et tu l''ajustes), avec la peste noire en option. Tu distribues de vraies cartes, ou le CLHUB les tire au sort : chacun scanne le QR code et découvre la sienne. La nuit, les appels arrivent dans l''ordre (que tu peux changer) et le CLHUB retient tout : amoureux, modèle de l''enfant sauvage, potions, protections. Au matin, il propose les morts, puis le vote du jour, et devine qui a gagné. Les joueurs ont un lien avec les règles des cartes du deck, et tu gardes les stats de tes parties.');
